-- 数据统计
-- ================================================
SELECT '✅ 数据填充完成！' AS message;
SELECT CONCAT('管理员: ', COUNT(*), ' 条') AS result FROM admin
UNION ALL
SELECT CONCAT('商户: ', COUNT(*), ' 条') FROM merchant
UNION ALL
SELECT CONCAT('用户: ', COUNT(*), ' 条') FROM user
UNION ALL
SELECT CONCAT('酒店: ', COUNT(*), ' 条') FROM hotel
UNION ALL
SELECT CONCAT('房型字典: ', COUNT(*), ' 条') FROM room_type
UNION ALL
SELECT CONCAT('酒店房型: ', COUNT(*), ' 条') FROM hotel_room
UNION ALL
SELECT CONCAT('标签: ', COUNT(*), ' 条') FROM tag
UNION ALL
SELECT CONCAT('酒店标签: ', COUNT(*), ' 条') FROM hotel_tag_relation
UNION ALL
SELECT CONCAT('预订: ', COUNT(*), ' 条') FROM room_booking;
